  const bBild={};
  for(const k in B_SPRITES){const im=new Image();im.src=B_SPRITES[k];bBild[k]=im;}

  // Jede Kategorie hat ihre EIGENE Basisrampe: der Koerper liegt im Ton "light", das Haar
  // aber im Ton "orange", Metall in "steel", Stoff in seinem ersten Ton. Wer ueberall die
  // Koerperrampe anlegt, faerbt Haar und Metall nie um — es sieht nur zufaellig passend aus.
  const bHex=a=>a.map(h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)]);
  const B_RAMPEN={koerper:bHex(B_PAL.light), haar:bHex(B_HAAR.orange),
    stoff:bHex(B_STOFF[Object.keys(B_STOFF)[0]]), metall:bHex(B_METALL.steel)};
  const B_TOENE={koerper:B_PAL, haar:B_HAAR, stoff:B_STOFF, metall:B_METALL};
  const bGefaerbt={};
  // DIE KOERPERRAMPE IST NICHT IMMER `light`.
  //
  // Der Kommentar oben hat recht — jede Kategorie hat ihre eigene Basisrampe — nur reicht
  // das eine Ebene zu kurz: auch INNERHALB der Kategorie Koerper liegen die Blaetter in
  // verschiedenen Rampen. Ausgezaehlt ueber alle zwanzig Kopfblaetter:
  //
  //   light      alien 99 %, human 97 %, vampire 96 %
  //   green      lizard 97 %, orc 95 %, troll 95 %, goblin 80 %
